function base(g,w,h,title,subtitle){g.setTransform(w/768,0,0,h/320,0,0);g.fillStyle=COLORS.ink;g.fillRect(0,0,768,320);const gr=g.createLinearGradient(0,0,0,320);gr.addColorStop(0,'rgba(47,79,89,.22)');gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.fillRect(0,0,768,320);g.fillStyle=COLORS.dim;g.font='600 12px Arial';g.fillText(title.toUpperCase(),19,24);g.textAlign='right';g.fillStyle=COLORS.cyan;g.font='11px monospace';g.fillText(subtitle||'TELEMETRY  /  SYNC',748,24);g.textAlign='left';g.fillStyle=COLORS.line;g.fillRect(18,36,732,1);g.fillStyle='#10252f';g.fillRect(0,299,768,21);g.fillStyle=COLORS.dim;g.font='10px monospace';g.fillText('STARSHIP  /  TRAINING FLIGHT SYSTEM',18,313);g.fillStyle=COLORS.cyan;g.fillRect(733,306,6,6);}
function label(g,text,x,y,color=COLORS.dim,size=11){g.fillStyle=color;g.font=`${size}px monospace`;g.fillText(text,x,y)}
function value(g,title,value,unit,x,y,size=30,color=COLORS.white){label(g,title,x,y);g.fillStyle=color;g.font=`400 ${size}px monospace`;g.fillText(value,x,y+size+9);g.font='11px monospace';g.fillStyle=COLORS.dim;g.fillText(unit,x,y+size+27)}
function line(g,x1,y1,x2,y2,col=COLORS.line){g.beginPath();g.moveTo(x1,y1);g.lineTo(x2,y2);g.strokeStyle=col;g.lineWidth=1;g.stroke()}
function bar(g,x,y,w,fraction,color=COLORS.cyan){g.fillStyle='#19333d';g.fillRect(x,y,w,5);g.fillStyle=color;g.fillRect(x,y,w*clamp(fraction,0,1),5)}
function timer(t){t=t??-120;let sec=Math.abs(t);return(t<0?'T−':'T+')+String(Math.floor(sec/60)).padStart(2,'0')+':'+String(Math.floor(sec%60)).padStart(2,'0')}
function rocket(g,x,y,h,stage=1){const w=h*.08;g.strokeStyle='#b9cbd0';g.lineWidth=1.4;g.beginPath();g.moveTo(x,y-h/2);g.quadraticCurveTo(x+w,y-h*.44,x+w,y-h*.25);g.lineTo(x+w,y+h/2);g.lineTo(x-w,y+h/2);g.lineTo(x-w,y-h*.25);g.quadraticCurveTo(x-w,y-h*.44,x,y-h/2);g.stroke();for(let i=0;i<10;i++)line(g,x-w,y-h*.22+i*h*.065,x+w,y-h*.22+i*h*.065,'#3b535e');g.strokeStyle=COLORS.dim;for(let side of [-1,1]){g.beginPath();g.moveTo(x+side*w,y+h*.26);g.lineTo(x+side*w*1.9,y+h*.43);g.lineTo(x+side*w,y+h*.41);g.stroke()}}
