function updateTelemetry(s,state){
 const I=s.interiors;if(!I)return;const c=state.capsule,active=!!c?.active;
 for(const screen of I.screens){
  if(screen.type==='pad'&&s.missionFeedMaterial?.map!==screen.map)continue;
  const crewDisplay=active&&['flight','nav','prop','sequence','environment'].includes(screen.type),recoveryDisplay=!active&&screen.type==='sequence'&&state.separated&&state.config?.recoveryMode;
  const st=active&&['flight','nav'].includes(screen.type)?{...state,_capsule:c,altitude:c.altitude,velocity:c.velocity,verticalVelocity:c.verticalVelocity,downrange:c.downrange,phase:(state.outcome||'').includes('CAPSULE IMPACT')?'IMPACT':c.phase,gForce:c.gForce,pitch:null,roll:null}:state;
  let title={flight:'PRIMARY FLIGHT DISPLAY',nav:'GUIDANCE / NAVIGATION',prop:'PROPULSION / HEALTH',status:(screen.options.station||'VEHICLE')+' / SYSTEM STATUS',wallstatus:'LAUNCH COMMIT POLL',sequence:'MISSION SEQUENCER',trajectory:'ASCENT TRAJECTORY',environment:'ENVIRONMENT / LIFE SUPPORT',comms:'COMMUNICATIONS',pad:'PAD CAMERA / OPTICAL'}[screen.type]||screen.type;
  if(crewDisplay)title={flight:'TRAINING CAPSULE / FLIGHT',nav:'TRAINING CAPSULE / NAVIGATION',prop:'TRAINING CAPSULE / PROPULSION',sequence:'TRAINING CAPSULE / ESCAPE SEQUENCE',environment:'TRAINING CAPSULE / RECOVERY'}[screen.type];
  else if(recoveryDisplay)title='INDEPENDENT VEHICLE RECOVERY';
  else if(active&&['status','trajectory','comms'].includes(screen.type))title='LAUNCH VEHICLE / '+({status:'SYSTEM STATUS',trajectory:'TRAJECTORY',comms:'COMMUNICATIONS'}[screen.type]);
  const phase=crewDisplay?(state.outcome.includes('CAPSULE IMPACT')?'IMPACT':c.phase):(state.phase||'PREFLIGHT');const subtitle=crewDisplay?'CAPSULE / '+phase:state.fault?'VEHICLE CAUTION / '+state.fault.toUpperCase():phase.replaceAll('_',' ');
  const g=screen.map.image.getContext('2d');base(g,screen.map.image.width,screen.map.image.height,title,subtitle);
  const draw=active&&screen.type==='prop'?capsuleProp:active&&screen.type==='sequence'?capsuleSequence:active&&screen.type==='environment'?capsuleRecovery:recoveryDisplay?recoverySequence:({flight,nav,prop,status,wallstatus,sequence,trajectory,environment,comms,pad:padFallback}[screen.type]||status);draw(g,st,screen.options.station);screen.map.needsUpdate=true;
 }
}
